# plan.py — покадровый план «Что если отмотать 10 секунд». Подключается из build_shots.py.
# Все фигуры одного размера (масштаб задаёт шаблон). Крупные лица — F(...). «Назад» — кадр с rew=True.
RF = -0.372          # стоит на крыше гаража
RL = -0.233           # лежит на крыше
GL = 0.13            # лежит на земле
TL = 0.09            # лежит на шинах
EDGE = 0.6           # край крыши, откуда падает Лёха
GSO = {'mood': 'golden'}
def att(n): return [{'k': 'badge', 'str': f'ПОПЫТКА {n}'}]
def badge(s, color=None): d = {'k': 'badge', 'str': s}; d.update({'color': color} if color else {}); return [d]
def R(spec, n=None):   # «Назад»: тот же кадр + эффект перемотки
    d = dict(spec); d['rew'] = True; d['_sfx'] = [{'at': 0.0, 'name': 'glitch', 'gain': -10}, {'at': 0.05, 'name': 'whoosh', 'gain': -12}]
    if n: d['ui'] = att(n)
    return d
def G(actors=(), **kw): kw.setdefault('so', GSO); return S('garage', actors, **kw)
LROOF = lambda x=EDGE, p='stand', e='neutral', **kw: L_(x, p, 1, e, dy=RF, **kw)
LFALL = lambda x=EDGE, e='shocked', k=(0.25, 0.75), to=GL, **kw: L_(x, 'fall', 1, e, dy=RF, dyTo=to, rot=0, rotTo=-1.45, dk=list(k), **kw)
AG = lambda x=0.8, p='stand', e='neutral', f=-1, **kw: A_(x, p, f, e, **kw)
def mk(c, x, p, f, e, extra): d = a(c, x, p, f, e); d.update(extra); return d
CA = lambda **kw: S('cafe', [mk('A', 0.43, 'sit', 1, kw.pop('ae', 'neutral'), kw.pop('aa', {})), mk('L', 0.57, 'sit', -1, kw.pop('le', 'neutral'), kw.pop('la', {}))], **kw)
BAR = lambda extra=(), **kw: S('bar', [A_(0.17, 'sit', 1, kw.pop('ae', 'neutral')), L_(0.26, 'sit', -1, kw.pop('le', 'neutral'))] + list(extra), **kw)
KM = lambda me='smile', ae='neutral', extra=(), **kw: S('kitchen', [mk('A', 0.14, 'sit', 1, ae, kw.pop('aa', {})), mk('MOM', 0.29, 'sit', -1, me, kw.pop('ma', {}))] + list(extra), cam=kw.pop('cam', {'k': 'slow', 'x': -400}), **kw)
LH = lambda le='neutral', ae='neutral', **kw: S('living', [mk('L', 0.74, 'sitBack', -1, le, {'chair': False, 'dy': -0.06, 'cast': kw.pop('cast', True), **kw.pop('la', {})}), mk('A', 0.6, 'sit', 1, ae, {'chair': False, 'dy': -0.06, **kw.pop('aa', {})})], **kw)
WD = lambda le='neutral', extra=(), **kw: S('ward', [mk('L', 0.55, 'sitBack', 1, le, {'chair': False, 'dy': -0.01, 'cast': True, **kw.pop('la', {})})] + list(extra), **kw)
ST = lambda extra=(), **kw: S('street', list(extra), so=kw.pop('so', {'mood': 'dusk'}), **kw)
SHOP = lambda extra=(), **kw: S('store', [a('CASHIER', 0.8, 'stand', -1, 'neutral')] + list(extra), **kw)
DD = lambda de='happy', ae='smile', **kw: S('living', [mk('DED', 0.72, 'sit', -1, de, {'chair': False, 'dy': -0.06, **kw.pop('da', {})}), A_(0.6, 'sit', 1, ae, chair=False, dy=-0.06)], **kw)
TIRE = lambda k: it('tire', 0.82, 0.8, 1, path=[[0, 0.8, 0.8, 0], [0.8, 0.58 + (k % 3) * 0.035, 0.8, 0], [1, 0.58 + (k % 3) * 0.035, 0.8, 0]])
def PUSH(k, cam='left'): return G([A_(0.78, walk=[0.86, 0.66], wk=[0, 0.7], e='determined')], so={'mood': 'dusk', 'wet': True, 'tiresN': max(0, 6 - k - 1), 'under': k}, items=[TIRE(k)], cam=cam, _sfx=[{'at': 0.3, 'name': 'footstep', 'gain': -10}])

